text:
&.link-button {
  background-color: transparent;
  color: var(--button-link-text-color);
  border-color: transparent;

  &:hover {
    background-color: transparent;
    color: var(--button-link-text-color);
    border-color: transparent;
    text-decoration: underline;
    cursor: pointer;

    &:active {
      background-color: transparent;
      color: var(--button-link-active-text-color);
      border-color: transparent;
    }
  }

  &.link-button-sm {
    text-decoration: underline;
    text-transform: uppercase;
    font-size: 0.8rem;
    cursor: pointer;
    padding: 0;
    --margin-for-outline: 2px;
    margin: var(--margin-for-outline) 0;
    min-block-size: calc(var(--button-min-height) - 2 * var(--margin-for-outline));
  }
